  next();
});
```

#### 7. No Logger with Security Context
**Issue**: Using console.log without proper logging middleware.

**Recommendation**: Add proper logging.

```javascript
const morgan = require('morgan');
app.use(morgan('combined', {
  skip: function (req, res) { return res.statusCode < 400 }
}));
```

#### 8. Best Practice Recommendations

**a. Environment Configuration**
```javascript
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

**b. Trust Proxy Settings**
```javascript
app.set('trust proxy', true);
```

**c. Disable x-powered-by Header**
```javascript
app.disable('x-powered-by');
```

**d. Readonly Environment**
```javascript
// Consider making environment variables readonly
if (process.env.NODE_ENV === 'production') {
  Object.freeze(process.env);
}
```

