```javascript
// app_compiled_secure.js
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const fs = require('fs');
const app = express();

// Security Configuration
app.use(helmet());
app.disable('x-powered-by');

// Rate Limit: 100 requests per 15 minutes per IP
app.use(rateLimit({ windowMs: 15 * 60 * 1000, max: 100 }));

// Security Headers
app.use((req, res, next) => {
  res.setHeader('Strict-Transport-Security', 'max-age=31536000');
  res.setHeader('Content-Security-Policy', "default-src 'self'");
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  next();
});

// Input Validation Middleware
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      status: 'error',
      message: 'Validation Error',
      details: errors.array()
    });
  }
  next();
};

// Secure Health Endpoint (public)
app.get('/health', [
  // Validate any query parameters
  query('format').optional().isString().isIn(['json', 'text']),
  validateRequest
], (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Protected Users Endpoint
app.get('/users', [
  // Authentication check should be added here
  query('limit').optional().isInt({ min: 1, max: 50}),
  query('offset').optional().isInt({ min: 0}),
  validateRequest
], (req, res) => {
  // Pagination example with validation
  const limit = parseInt(req.query.limit) || 20;
  const offset = parseInt(req.query.offset) || 0;

  // Mock data - should be replaced with secure database connection
  const users = [
