  });
});

// Error Handling Middleware
app.use((err, req, res, next) => {
  console.error(`[ERROR] ${err.message}`);
  res.status(500).json({
    status: 'error',
    message: 'Internal Server Error',
    errorId: crypto.randomBytes(4).toString('hex')
  });
});

// Route Not Found Handler
app.use((req, res) => {
  res.status(404).json({ status: 'error', message: 'Not Found' });
});

// Security Check: Remove dangerous credentials from filesystem
try {
  if (fs.existsSync('.env.test')) {
    fs.unlinkSync('.env.test');
    console.warn('Security: Removed .env.test file with credentials');
  }
} catch (err) {
  console.error('Security warning: Could not remove .env.test');
}

app.listen(3000, () => {
  console.log('Secure Server running on port 3000');
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;
```

## SECRET MANAGEMENT RECOMMENDATIONS

### 1. IMMEDIATE ACTIONS
```bash
